#include <iostream>
#include <stdexcept>
#include <string>
#include <vector>

template <typename T>
class Checked
{
public:
    explicit Checked(std::vector<T>& v) : m_v{v} {}
    T& operator[](std::size_t i) { return m_v[i]; }

private:
    std::vector<T>& m_v;
};

int main()
{
    std::vector<int> v{10, 20, 30};
    std::cout << Checked{v}[2] << '\n';
}
